// UGS.js – Rename, shuffle, and search for UGS Files
(function() {
    const MAPPING_URL = '';

    function renameButtons(map) {
        document.querySelectorAll('.buttons-container > *').forEach(function(btn) {
            let raw = (btn.value || btn.textContent || '').trim();
            // Strip the 'cl' prefix and '.html' extension to get the key
            let key = raw.replace(/^cl/i, '').replace(/\.html$/i, '');
            let display = map[key] || key;
            if (btn.tagName.toLowerCase() === 'input') {
                btn.value = display;
            } else {
                btn.textContent = display;
            }
        });
    }

    function shuffleButtons() {
        const container = document.getElementById('sections-container');
        if (!container) return;
        const buttonsContainers = container.querySelectorAll('.buttons-container');
        const allButtons = [];
        buttonsContainers.forEach(function(c) {
            while (c.firstChild) {
                allButtons.push(c.firstChild);
                c.removeChild(c.firstChild);
            }
        });
        // Fisher–Yates shuffle
        for (let i = allButtons.length - 1; i > 0; i--) {
            const j = Math.floor(Math.random() * (i + 1));
            [allButtons[i], allButtons[j]] = [allButtons[j], allButtons[i]];
        }
        // Re‑build a single section
        container.innerHTML = '';
        const sec = document.createElement('div');
        sec.className = 'letter-section';
        const btns = document.createElement('div');
        btns.className = 'buttons-container';
        allButtons.forEach(function(b) { btns.appendChild(b); });
        sec.appendChild(btns);
        container.appendChild(sec);
    }

    function setupSearch() {
        const searchInput = document.getElementById('searchInput');
        const noResults = document.getElementById('noResults');
        if (!searchInput) return;
        searchInput.addEventListener('input', function(e) {
            const term = e.target.value.toLowerCase().trim();
            const buttons = document.querySelectorAll('.buttons-container > *');
            let visible = 0;
            buttons.forEach(function(btn) {
                const text = (btn.value || btn.textContent || '').toLowerCase();
                if (term === '' || text.includes(term)) {
                    btn.style.display = '';
                    visible++;
                } else {
                    btn.style.display = 'none';
                }
            });
            if (noResults) {
                noResults.style.display = (visible === 0 && term !== '') ? 'block' : 'none';
            }
        });
    }

    function init() {
        // 1. Fetch the name mapping
        fetch(MAPPING_URL)
            .then(function(response) {
                if (!response.ok) throw new Error('Mapping file not found');
                return response.text();
            })
            .then(function(base64Text) {
                const nameMap = JSON.parse(atob(base64Text.trim()));
                renameButtons(nameMap);
                // 2. Shuffle after renaming
                shuffleButtons();
                // 3. Activate search
                setupSearch();
            })
            .catch(function(err) {
                console.warn('Could not load name mapping, using raw names.', err);
                // Fallback: still shuffle and search without renaming
                shuffleButtons();
                setupSearch();
            });
    }

    // Wait until the sections-container has buttons (games.js has loaded)
    function waitForButtons() {
        if (document.querySelectorAll('.buttons-container > *').length > 0) {
            init();
        } else {
            setTimeout(waitForButtons, 100);
        }
    }

    if (document.readyState === 'complete' || document.readyState === 'interactive') {
        waitForButtons();
    } else {
        window.addEventListener('DOMContentLoaded', waitForButtons);
    }
})();
